const hasOwn = Object.hasOwn;
/** Dispatch own array entries in order; rejection stops subsequent side effects. */
export async function forEachSequential(values, visit) {
    const next = async (index) => {
        while (index < values.length && !hasOwn(values, index))
            index++;
        if (index >= values.length)
            return;
        await visit(values[index]);
        return next(index + 1);
    };
    return next(0);
}
/** Find the first matching own entry without starting later source discovery. */
export async function findSequential(values, matches) {
    const next = async (index) => {
        while (index < values.length && !hasOwn(values, index))
            index++;
        if (index >= values.length)
            return undefined;
        const value = values[index];
        if (await matches(value))
            return value;
        return next(index + 1);
    };
    return next(0);
}
